"use client";

/**
 * Admin editor for an article's adapted reading levels (#1303). Each level
 * (A2–C1) can be written by hand (headline + plain-text paragraphs separated
 * by blank lines), generated by the LEVEL_ADAPT job when AI is configured, or
 * removed. The original article text is always available as "Original".
 */

import { useState, type SubmitEvent } from "react";
import { useRouter } from "next/navigation";
import { clientErrorMessage, deleteJson, postJson, putJson } from "@/lib/client-fetch";
import {
  ARTICLE_LEVEL_KEYS,
  readingLevelLabel,
  type ArticleLevelKey,
} from "@/lib/article-levels/levels";
import { Badge, Button, Field, Input, PanelError, Textarea } from "@/components/ui";
import ConfirmAction from "@/components/ConfirmAction";

export type AdminLevel = {
  levelKey: ArticleLevelKey;
  title: string;
  text: string;
  wordCount: number;
  lexileApprox: number | null;
  cefrLevel: string | null;
  source: string;
};

const LEVEL_TITLE_MAX = 300;
const LEVEL_TEXT_MAX = 60_000;

function LevelRow({
  articleId,
  levelKey,
  level,
  aiConfigured,
}: {
  articleId: string;
  levelKey: ArticleLevelKey;
  level: AdminLevel | undefined;
  aiConfigured: boolean;
}) {
  const router = useRouter();
  const [editing, setEditing] = useState(false);
  const [title, setTitle] = useState(level?.title ?? "");
  const [text, setText] = useState(level?.text ?? "");
  const [pending, setPending] = useState<"save" | "generate" | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const url = `/api/admin/articles/${encodeURIComponent(articleId)}/levels/${levelKey}`;
  const label = readingLevelLabel(levelKey);

  async function save(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending("save");
    setError(null);
    try {
      await putJson(url, { title, text });
      setEditing(false);
      setMessage("Saved.");
      router.refresh();
    } catch (err) {
      setError(clientErrorMessage(err, "Couldn’t save the level."));
    } finally {
      setPending(null);
    }
  }

  async function generate() {
    setPending("generate");
    setError(null);
    try {
      await postJson(`${url}/generate`, { replace: Boolean(level) });
      setMessage("Generation queued — refresh in a minute.");
    } catch (err) {
      setError(clientErrorMessage(err, "Couldn’t queue generation."));
    } finally {
      setPending(null);
    }
  }

  return (
    <li className="flex flex-col gap-[var(--space-2)] border-b border-border pb-[var(--space-3)] last:border-0">
      <div className="flex flex-wrap items-center gap-[var(--space-2)]">
        <span className="font-semibold text-text">{label}</span>
        {level ? (
          <>
            <Badge variant="success">{level.source === "ai" ? "AI generated" : "Manual"}</Badge>
            <span className="text-[length:var(--type-ui)] text-text-muted">
              {level.wordCount} words · measured {level.cefrLevel ?? "—"} / ~{level.lexileApprox ?? "—"}L
            </span>
          </>
        ) : (
          <Badge variant="neutral">Not added</Badge>
        )}
        {!editing ? (
          <span className="ml-auto flex flex-wrap gap-[var(--space-2)]">
            <Button
              type="button"
              size="sm"
              variant="outline"
              aria-label={`${level ? "Edit" : "Add"} level ${levelKey}`}
              onClick={() => {
                setTitle(level?.title ?? "");
                setText(level?.text ?? "");
                setEditing(true);
              }}
            >
              {level ? "Edit" : "Add"}
            </Button>
            {aiConfigured ? (
              <Button
                type="button"
                size="sm"
                variant="ghost"
                loading={pending === "generate"}
                disabled={pending !== null}
                aria-label={`Generate level ${levelKey} with AI`}
                onClick={() => void generate()}
              >
                {level ? "Regenerate" : "Generate"}
              </Button>
            ) : null}
            {level ? (
              <ConfirmAction
                triggerLabel="Delete"
                triggerAriaLabel={`Delete level ${levelKey}`}
                triggerVariant="danger-ghost"
                size="sm"
                confirmMessage={`Delete the ${levelKey} level and its quiz? Readers fall back to the original text.`}
                loading={deleting}
                onConfirm={async () => {
                  setDeleting(true);
                  try {
                    await deleteJson(url);
                    router.refresh();
                  } catch (err) {
                    setError(clientErrorMessage(err, "Couldn’t delete the level."));
                  } finally {
                    setDeleting(false);
                  }
                }}
              />
            ) : null}
          </span>
        ) : null}
      </div>
      {editing ? (
        <form onSubmit={save} className="flex flex-col gap-[var(--space-3)]">
          <Field label={`${levelKey} headline`}>
            <Input value={title} maxLength={LEVEL_TITLE_MAX} onChange={(event) => setTitle(event.target.value)} />
          </Field>
          <Field label={`${levelKey} text`} hint="Plain text. Separate paragraphs with a blank line.">
            <Textarea value={text} rows={10} maxLength={LEVEL_TEXT_MAX} onChange={(event) => setText(event.target.value)} />
          </Field>
          <div className="flex gap-[var(--space-2)]">
            <Button type="submit" size="sm" loading={pending === "save"} disabled={pending !== null || !title.trim() || !text.trim()}>
              Save level
            </Button>
            <Button type="button" size="sm" variant="ghost" onClick={() => setEditing(false)}>
              Cancel
            </Button>
          </div>
        </form>
      ) : null}
      {message ? (
        <p role="status" className="m-0 text-[length:var(--type-ui)] text-text-muted">
          {message}
        </p>
      ) : null}
      {error ? <PanelError message={error} /> : null}
    </li>
  );
}

export default function AdminArticleLevels({
  articleId,
  levels,
  aiConfigured,
}: {
  articleId: string;
  levels: AdminLevel[];
  aiConfigured: boolean;
}) {
  return (
    <ul aria-label="Reading levels" className="m-0 flex list-none flex-col gap-[var(--space-3)] p-0">
      {ARTICLE_LEVEL_KEYS.map((levelKey) => (
        <LevelRow
          key={levelKey}
          articleId={articleId}
          levelKey={levelKey}
          level={levels.find((level) => level.levelKey === levelKey)}
          aiConfigured={aiConfigured}
        />
      ))}
    </ul>
  );
}
